"""Render the repository experiment report from recorded accounting and reviews."""
from collections import Counter
from datetime import datetime,timezone
import json
from pathlib import Path
P=Path(__file__).resolve().parent
def read(name):return json.loads((P/name).read_text())
def pct(a,b):return f'{a/b*100:.2f}%' if b else 'N/A'
def safe(s):return str(s if s is not None else '—').replace('|','／').replace('\n',' ')
def main():
 s=read('summary.json');plan=read('plan.json');outs=read('outcomes.json');reviews=read('reviews.json');cost=s['cost'];n=s['actually_requested'];d=s['results'].get('date',0)
 stats={}
 for brand in plan['brands']:
  rs=[r for r in reviews if r['brand']==brand];with_ev=[r for r in rs if r['llm_date'] and r['has_evidence']];evaluated=[r for r in with_ev if r['correct'] is not None];no_ev=[r for r in rs if r['llm_date'] and not r['has_evidence']];correct=sum(r['correct'] for r in evaluated);supported=sum(r['original_evidence_supported'] is True for r in rs);usable=sum(r['original_evidence_supported'] is True and r['correct'] is True for r in rs)
  stats[brand]=dict(samples=len(rs),date_samples=sum(bool(r['llm_date']) for r in rs),raw_evidence_present=len(with_ev),date_accuracy_evaluable=len(evaluated),date_correct=correct,date_accuracy=correct/len(evaluated) if evaluated else None,missing_raw_evidence=len(no_ev),missing_raw_evidence_date_matches=sum(r['correct'] is True for r in no_ev),original_evidence_supported=supported,original_evidence_unverified=sum(r['original_evidence_supported'] is None for r in rs if r['llm_date']),usable_correct=usable,abstention_samples=sum(r['llm_date'] is None for r in rs))
 (P/'accuracy.json').write_text(json.dumps(stats,ensure_ascii=False,indent=2)+'\n')
 lines=['# 全库 LLM 发布时间填充率实验（仅 staging）','',f'实际响应模型：**{", ".join(s["actual_response_models"])}**。全库 **{s["total_families"]} 族 = 已有 official 跳过 {s["skipped_official"]} 族 + 实跑 {n} 族**。给日期 **{d} 族**，实跑填充率 **{d}/{n} = {pct(d,n)}**；相对全库族数 **{d}/{s["total_families"]} = {pct(d,s["total_families"])}**。','',f'全部候选无条件采纳的机械上限：release.date 非空 **{s["baseline_rows"]}/{s["total_rows"]} = {pct(s["baseline_rows"],s["total_rows"])} → {s["hypothetical_date_rows"]}/{s["total_rows"]} = {pct(s["hypothetical_date_rows"],s["total_rows"])}**，净增 {s["candidate_new_rows"]} 行。这只是非空覆盖预估，未经过质量门禁，不是可用事实覆盖。','', '实验未修改 public/goods.json、_data/public/goods.json、官方/LLM/交叉核查输入或 API 代码，未发布。生产文件逐项前后 hash 见 validation.json。','', '## 分母与结果','',f'- 总行数 {s["total_rows"]}，唯一 ID 3963；5 次重复 ID 属于不同分类，保留原库行数，不缩分母。', '- 聚族沿用现有 family_model，先对所有行聚族，再按 brand/category/去空白型号形成键，扩展到七品牌。惠普保留CPU/GPU、套机跟body_id。之前约2813是四品牌缺日期子集，不是本次七品牌全库分母。', '- 任一族成员已有 source=official 且 date 非空，整族不请求；族内其他缺日期成员也不借官方日期自动填充。已有 third_party/llm 的族仍请求，覆盖预估不把旧日期重复计成新增。跳过的官方族内仍有185行缺日期（大疆156、Apple25、富士4），这些行不自动填充。', '- 冻结重建基线与实取线上快照的 (id,brand,category,聚族型号,date,source) 多重集合一致；79条 release 展示/检查元数据不同，不影响本次分母、跳过或覆盖。见 live-baseline-comparison.json。','', '|实跑结果|族数|', '|---|---:|',f'|成功返回非空正文（下三项之和）|{s["successful_returns"]}|',f'|弃答：JSON date=null|{s["results"].get("abstention",0)}|',f'|给日期：合法 YYYY-MM，是否有依据另列|{d}|',f'|格式非法：JSON解析失败、缺date或非法日期|{s["results"].get("invalid_format",0)}|',f'|请求失败/空响应|{s["results"].get("request_failed",0)}|',f'|待执行/在途|{s["results"].get("pending",0)+s["results"].get("in_flight",0)}|','', '成功返回是传输/正文口径，不表示日期正确。弃答只算没有日期，不参与日期准确率。格式合法但没有依据也算填充候选，并在质量统计单列。','', '|品牌|总族|已有官方跳过|实跑|成功返回|弃答|给日期|非法|实跑填充率|日期/总族|', '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for b,v in s['brands'].items():lines.append(f'|{b}|{v["total"]}|{v["official"]}|{v["requested"]}|{v["success"]}|{v.get("abstention",0)}|{v.get("date",0)}|{v.get("invalid_format",0)}|{pct(v.get("date",0),v["requested"])}|{pct(v.get("date",0),v["total"])}|')
 no_evidence=Counter(o['brand'] for o in outs if o['result']=='date' and not o['has_evidence'])
 lines+=['','## 成本与执行','',f'- 请求数 **{cost["requests"]}**（包含429重试）；墙钟 **{s["wall_seconds"]:.3f} 秒 / {s["wall_seconds"]/60:.2f} 分钟**，以首个session开始到最后session完成计时，包含熔断后的暂停/冷却、初始化状态、请求等待与落盘；不含最后请求完成后的抽样核对及报告时间。',f'- input/prompt tokens **{cost.get("prompt_tokens",0):,}**；output/completion tokens **{cost.get("completion_tokens",0):,}**；total **{cost.get("total_tokens",0):,}**。',f'- 429 **{cost["http_429"]}** 次；计划退避合计 **{cost["backoff_scheduled_seconds"]:.3f} 秒**，实际退避合计 **{cost["backoff_elapsed_seconds"]:.3f} 秒**（worker求和，不等于墙钟）。', f'- 共{s["sessions"]}个执行session、{s["circuit_events"]}次熔断，session内活动墙钟合计{s["active_session_seconds"]:.3f}秒；每次解除均先检查429记录并冷却，历史保存在circuit-history/。', '- 6个worker，全局4QPS，按完成顺序连续3次429持久熔断；仅429重试，1/2/4/8秒指数退避并尊重Retry-After。SIGINT/SIGTERM停止新派发并等待在途落盘；已成功族续跑不重发，未知中断计费沿用现有链路标记。', '- Token合计只来自已记录的响应usage；429没有返回usage，不把未知计费断言为零。金额不可得：网关未提供本次计费单价，不能把token数折成虚构人民币金额。实际响应模型逐响应读取，不使用请求路由名作为模型身份。', '', '## 抽样准确率与依据','', '每品牌完成后，按固定seed=20261103从排序后的合法日期族随机抽10条；日期不足10条则全取日期候选，并从余下结果补足10条。样本先冻结再检索，不替换错误条目。小米汽车只有3族且全部已有official，不请求，所以其LLM样本数0，无法满足10条，明确记N/A，不能伪造样本或破坏跳过要求。', '', '“给过依据”仅指模型原evidence字面含URL或quote（不代表引用正确或网页已验证），reason自述不算依据；“原依据支持”要求读到模型原引用能支持准确型号与公告月份。事后找到的新链接仅核对日期，不补改模型原依据。日期准确率只以字面给过URL/quote且取得独立真值的日期样本作分母，错引仍留在此分母中，另由原依据支持率揭示；无原依据另外列出，不混入该准确率。另报“日期正确且原依据支持/全部日期样本”，防止日期猜对掩盖错引。原引用抓取失败只记未核实，不据此断言网页不存在。', '', '|品牌|抽样数/日期数|日期准确率（给过URL/引文）|日期有值但无依据|原依据待核实|原依据支持/日期样本|日期对且原依据支持/日期样本|弃答样本|', '|---|---:|---:|---:|---:|---:|---:|---:|']
 for b,v in stats.items():lines.append(f'|{b}|{v["samples"]}/{v["date_samples"]}|{v["date_correct"]}/{v["date_accuracy_evaluable"]} {pct(v["date_correct"],v["date_accuracy_evaluable"])}|{v["missing_raw_evidence"]}|{v["original_evidence_unverified"]}|{v["original_evidence_supported"]}/{v["date_samples"]}|{v["usable_correct"]}/{v["date_samples"]}|{v["abstention_samples"]}|')
 lines+=['',f'全体日期候选中，没有URL/quote依据的计数：{dict(no_evidence)}（合计{sum(no_evidence.values())}）。date非空却同时给abstention_reason的品牌计数：{s["date_with_abstention_reason"]}。这些按实际date字段计入候选，不把文字自称弃答改写成date=null。完整原始evidence、逐条结论和核对来源在 reviews.json；本次60条样本（48条给日期、12条弃答）并不保证总体准确率，也不能把同一份来源下的多个型号当作独立质量保证。', '', '|品牌|型号|LLM年月|给过依据/原依据支持|核对结果|正确值|核对说明与来源|', '|---|---|---|---|---|---|---|']
 for r in reviews:
  verdict='对' if r['correct'] is True else '错' if r['correct'] is False else '不计（弃答或真值未取得）'
  supported='是' if r['original_evidence_supported'] is True else '否' if r['original_evidence_supported'] is False else '未核实'
  link=f'[{safe(r["verification_note"])}]({r["verification_url"]})' if r.get('verification_url') else safe(r['verification_note'])
  lines.append(f'|{r["brand"]}|{safe(r["model"])}|{safe(r["llm_date"])}|{"有" if r["has_evidence"] else "无"}/{supported}|{verdict}|{safe(r["correct_date"])}|{link}|')
 lines+=['','## 使用判断', '', '这批结果适合作为人工核对候选。样本中存在错月份、把上市月当首次公告月、借系列日期、原URL指向其他商品及date与弃答说明自相矛盾；有URL不等于有可用证据。即使月份准确率较高，也不能把整批直接当作正式发布时间。此实验仅回答填充率和抽样质量，不执行采纳。', '', '## 复现、断点与产物','', '冻结输入在 baseline-goods.json，实取API响应在 baseline-response.json；原始逐族响应（含原始JSON字符串、model、usage、captured_at、每次attempt）在 responses/，状态在 states/，发送标记在 sent/。这些文件均以字节原样收入 raw-artifacts.tar.gz，sha256清单为 artifact-manifest.json。冻结族与跳过名单、汇总和报告在同目录独立保存，未写正式字段。','', '```bash', '# 如从提交恢复，先解开完整原始文件，再执行；成功族不重发', 'cd staging/release-full-20261103', 'tar -xzf raw-artifacts.tar.gz', 'cd ../..', 'python staging/release-full-20261103/experiment.py run', 'python staging/release-full-20261103/experiment.py assemble', 'python staging/release-full-20261103/review_verdicts.py', 'python staging/release-full-20261103/validate_experiment.py', 'python staging/release-full-20261103/make_report.py', '```', '', '如circuit.json存在，先检查原因，再显式传 --resume-after-circuit；不自动越过熔断。本次实际执行是否完整以summary/validation为准，不以复现命令冒充执行记录。', '', '相关测试见 tests.log；抽样冻结和来源抓取记录在review-queue.json、verification/；生产不变量与全局派发间隔见validation.json。']
 (P/'README.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':main()
